from pybricks.parameters import Button, Stop
from pybricks.tools import multitask, run_task, wait

from robot_config import DRIVE_BASE, HUB, SPEED, SPEED850, lift, tilt

async def subtask():
    await wait(1000)
    while not Button.RIGHT in HUB.buttons.pressed():
        await wait(0)

async def subtask2():
    DRIVE_BASE.settings(straight_speed=SPEED850)
    await tilt.run_angle(500, 180)

async def seed():
    await wait(0)
    await HUB.speaker.beep(300, 100)
    tilt.reset_angle(0)
    HUB.imu.reset_heading(0)
    await wait(100)
    DRIVE_BASE.use_gyro(True)
    DRIVE_BASE.settings(straight_speed=SPEED)
    await multitask(
        subtask(),
        subtask2(),
        race=True,
    )
    while not DRIVE_BASE.stalled():
        await wait(0)
        await DRIVE_BASE.straight(310)

async def main():
    # Blank,  done to make code multitask
    # Needed due to how the blocks work
    await multitask(
        wait(0),
    )


run_task(main())